#!/usr/bin/env python3
"""Offline finite owned-ABI classification; no swap amounts sourced from decoder rows."""
import argparse,pathlib,json,hashlib,subprocess,sys,collections
p=argparse.ArgumentParser();p.add_argument('--node-dependency-package',required=True);p.add_argument('--protobuf-package',required=True);p.add_argument('--block-cache',default='/nonexistent-classification-cache');a=p.parse_args();base=pathlib.Path(__file__).resolve().parent
subprocess.run(['node',str(base/'verify-owned-idls.cjs'),str(base/'primary'),a.node_dependency_package],check=True)
subprocess.run(['node',str(base/'inspect-originals.cjs'),a.node_dependency_package,a.protobuf_package],check=True,stdout=subprocess.DEVNULL)
facts=json.loads((base/'facts.json').read_text());originals={}
for r in facts:
 sig=r['signature'];files={ext:base/'originals'/(sig+ext)for ext in['.pb','.rpc.json']};originals[sig]={'signature':sig,'slot':r['block_num'],'pbPath':str(files['.pb']),'rpcPath':str(files['.rpc.json']),'pbSha256':hashlib.sha256(files['.pb'].read_bytes()).hexdigest(),'rpcSha256':hashlib.sha256(files['.rpc.json'].read_bytes()).hexdigest()}
input=base/'original-inputs.json';input.write_text(json.dumps({'originals':list(originals.values())})+'\n')
subprocess.run(['node',str(base/'original-metadata.cjs'),str(input),a.block_cache,str(base/'original-metadata.json'),'--node-dependency-package',a.node_dependency_package,'--protobuf-package',a.protobuf_package,'--prepare'],check=True)
subprocess.run([sys.executable,str(base/'classify.py')],check=True,stdout=subprocess.DEVNULL)
rows=json.loads((base/'typed.json').read_text());assert len(rows)==391 and len(originals)==203 and all(r.get('spotSwap')is False for r in rows)
proof={'scope':'391 finite no-indexed-native-child source instructions in finalized slots456213447..456214372,17 owned-IDL programs,203 original transactions; no global coverage claim.','counts':{'sources':len(rows),'transactions':len(originals),'newSpotSwaps':0,'categories':dict(collections.Counter(r['classification']for r in rows)),'status':dict(collections.Counter(r['status']for r in rows)),'wholeProtectedTokenLedgers':sum(len(r.get('wholeTokenLedgers',[]))for r in rows)},'originals':rows,'limitations':['All original PB/finalized transaction RPC metadata and committed runtime checked. Containing block cache optional; no containing block order/hash claim without it.','The373 exact owned ABI sources retain full principal flows; complete protected token ledger checks are claimed only for308 vault,10 stock receipt,2 privacy deposit sources, totaling650 ledgers.','Launchlab1/Streamflow1 have exact known argument prefixes and retained10-byte suffixes, excluded by initialization/escrow flows; suffix meaning is not inferred.','Umbra deployed40-byte arguments differ from later ownedIDL fee-proof form; exact binary reads and single-asset custody principals retained.','FewR ownedIDL empty; deployed issuer stock-facility dispatch/log/argument read and exact receipt flows prove finite redemption business action; no historical configured exchange ratio claimed.']}
(base/'classification-proof.json').write_text(json.dumps(proof,indent=2)+'\n');print(json.dumps(proof['counts']))
